          { id: 'nov-dec', icon: '❄️', label: 'Nov–Dec', count: urgencyCounts['Nov–Dec'] || 0 },
          { id: 'mar-apr', icon: '🌱', label: 'Mar–Apr', count: urgencyCounts['Mar–Apr'] || 0 }
